<script setup lang="ts">
import {computed,ref,onMounted,watch,onUnmounted} from 'vue'
import {useMerchantStorageText} from './merchant/text'
import type {StorageApi} from './api'
import type {Application,Home,ReceiptLine,Product} from './types'
import StoragePhotos from './StoragePhotos.vue'
const props=defineProps<{api:StorageApi;application:Application;home:Home;disabled:boolean;direct?:boolean}>(),emit=defineEmits<{saved:[];error:[string];'busy-change':[boolean]}>(),{t}=useMerchantStorageText()
const lines=ref<ReceiptLine[]>(props.application.lines.map(l=>({lineId:l.id,productId:l.productId,categoryId:'',nameZh:l.nameZh,nameEn:l.nameEn,quantity:l.quantity,opened:l.opened,source:l.source,ruleId:'',photos:[],note:l.note,location:'',label:''}))),reason=ref(props.direct?t('registrationReason'):''),rulesConfirmed=ref(false),query=ref(''),candidates=ref<Product[]>([]),uploading=ref(0),saving=ref(false)
const matchesOriginal=computed(()=>lines.value.length===props.application.lines.length&&lines.value.every(line=>props.application.lines.some(original=>original.id===line.lineId&&original.productId===line.productId&&original.quantity===line.quantity&&original.opened===line.opened&&original.source===line.source)))
async function search(){try{candidates.value=await props.api.get<Product[]>('/products?query='+encodeURIComponent(query.value));for(const line of lines.value){if(!line.ruleId&&line.productId)choose(line,line.productId)}}catch(e){emit('error',String(e))}}
onMounted(()=>{query.value=props.application.lines[0]?.nameZh||props.application.lines[0]?.nameEn||'';void search()})
function choose(line:ReceiptLine,id:string){const p=candidates.value.find(x=>x.id===id);if(p){line.productId=p.id;line.categoryId=p.categoryId;line.nameZh=p.nameZh;line.nameEn=p.nameEn;line.ruleId=props.home.rules.find(r=>r.categoryId===p.categoryId)?.id??''}}
watch([saving,uploading],()=>emit('busy-change',saving.value||uploading.value>0),{flush:'sync'})
onUnmounted(()=>emit('busy-change',false))
function addLine(line:ReceiptLine){lines.value.push({...line,lineId:props.direct?crypto.randomUUID():line.lineId,quantity:1,opened:props.direct?false:true,photos:[],label:''})}
function validLine(line:ReceiptLine){return !!line.ruleId&&line.photos.length>0&&Number.isInteger(line.quantity)&&line.quantity>=1&&line.quantity<=(line.opened?1:10000)&&!!(line.productId||(line.categoryId&&(line.nameZh.trim()||line.nameEn.trim())))}
async function submit(){if(props.disabled||saving.value||uploading.value||!reason.value.trim()||(props.direct&&!rulesConfirmed.value)||!lines.value.length||lines.value.some(l=>!validLine(l)))return;saving.value=true;try{await props.api.command(props.direct?'/registrations':`/applications/${props.application.id}/receive`,{lines:lines.value,reason:reason.value,...(props.direct?{customerId:props.application.customerId,rulesConfirmed:rulesConfirmed.value}:{})});emit('saved')}catch(e){emit('error',String(e))}finally{saving.value=false}}
</script>
<template><form class="storage-panel" @submit.prevent="submit"><fieldset :disabled="disabled||saving||uploading>0"><h3>{{t(direct?'directRegister':'receive')}}</h3><p class="cards-muted">{{t('receiveHint')}}</p><p v-if="direct" class="storage-notice">{{t('expiryHint')}}</p><label>{{t('wineSearch')}}<input v-model="query" maxlength="120"></label><button type="button" :disabled="disabled||saving" @click="search">{{t('wineSearch')}}</button><article v-for="(l,index) in lines" :key="index" class="storage-panel"><p v-if="l.nameZh||l.nameEn">{{l.nameZh}}<template v-if="l.nameZh&&l.nameEn"> / </template>{{l.nameEn}}</p><button type="button" :disabled="disabled||saving||lines.length>=(direct?50:100)" @click="addLine(l)">{{t(direct?'addBottle':'add')}}</button><button v-if="direct?lines.length>1:lines.filter(x=>x.lineId===l.lineId).length>1" type="button" @click="lines.splice(index,1)">{{t('remove')}}</button><label>{{t('candidates')}}<select :value="l.productId" @change="choose(l,($event.target as HTMLSelectElement).value)"><option value="">—</option><option v-if="l.productId&&!candidates.some(p=>p.id===l.productId)" :value="l.productId">{{l.nameZh||l.nameEn}}</option><option v-for="p in candidates" :key="p.id" :value="p.id">{{p.nameZh||p.nameEn}} · {{p.code}}</option></select></label><label><input :checked="!l.productId" type="checkbox" @change="l.productId=null">{{t('newProduct')}}</label><template v-if="!l.productId"><label>{{t('nameZh')}}<input v-model="l.nameZh" maxlength="200"></label><label>{{t('nameEn')}}<input v-model="l.nameEn" maxlength="200"></label><label>{{t('category')}}<select v-model="l.categoryId" required><option value="">—</option><option v-for="c in home.categories" :key="c.id" :value="c.id">{{c.nameZh||c.nameEn}}</option></select></label></template><label>{{t('quantity')}}<input v-model.number="l.quantity" type="number" required min="1" :max="l.opened?1:10000"></label><select v-model="l.opened" @change="l.opened&&(l.quantity=1)"><option :value="false">{{t('whole')}}</option><option :value="true">{{t('opened')}}</option></select><select v-model="l.source"><option value="store">{{t('store')}}</option><option value="customer">{{t('customer')}}</option></select><label>{{t('rules')}}<select v-model="l.ruleId" required><option value="">—</option><option v-for="r in home.rules.filter(r=>!l.categoryId||r.categoryId===l.categoryId)" :key="r.id" :value="r.id">{{r.name}} · {{r.months}} {{t('months')}} · v{{r.version}}</option></select></label><StoragePhotos v-model="l.photos" :api="api" :customer-id="application.customerId" :disabled="disabled||saving" @busy="uploading=Math.max(0,uploading+($event?1:-1))" @error="emit('error',$event)"/><label>{{t('location')}}<input v-model="l.location" maxlength="200"></label><label>{{t('label')}}<input v-model="l.label" maxlength="200"></label><label>{{t('note')}}<textarea v-model="l.note" maxlength="2000"/></label></article><button v-if="!direct" type="button" :disabled="disabled||saving||uploading>0||!matchesOriginal" @click="reason=t('matchesApplication')">{{t('matchesApplication')}}</button><label v-if="direct"><input v-model="rulesConfirmed" type="checkbox" required>{{t('registrationConsent')}}</label><label>{{t('reason')}}<textarea v-model="reason" required maxlength="2000"/></label><button :disabled="disabled||saving||uploading>0||lines.some(l=>!validLine(l))||!reason.trim()||(direct&&!rulesConfirmed)">{{t(direct?'registerSubmit':'receive')}}</button></fieldset></form></template>
